import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../ricos-types/index.js';
import { TextSelection } from './../tiptap/pm/state.js';
import {
  createRicosNodeExtension,
  withBreakoutContainer,
} from './../plugin-commons/index.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';

import { ROOT } from './data-hooks.js';
import styles from './statics/styles/code-block-scss.js';

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    codeBlock: {
      /**
       * Set a code block
       */
      setCodeBlock: (attributes?: { language: string }) => ReturnType;
      /**
       * Toggle a code block
       */
      toggleCodeBlock: (attributes?: { language: string }) => ReturnType;
    };
  }
}

const backtickInputRegex = /^```(?<language>[a-z]*)?[\s\n]$/;
const tildeInputRegex = /^~~~(?<language>[a-z]*)?[\s\n]$/;

export const tiptapExtensions: RicosExtension[] = [
  createRicosNodeExtension({
    groups: ['shortcuts-enabled'],
    type: 'html-node',
    name: Node_Type.CODE_BLOCK,
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>,
      services: TiptapAdapterServices
    ) => ({
      ...config,
      addOptions() {
        return {
          services,
          languageClassPrefix: 'language-',
          HTMLAttributes: {
            class: styles.code,
          },
          ...settings,
        };
      },
    }),

    createExtensionConfig({ Plugin, PluginKey, textblockTypeInputRule, mergeAttributes }) {
      return {
        name: this.name,

        content: '(text|specialCharacter)*',

        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemTitleContent collapsibleListItemBodyContent tableCellContent',

        code: true,

        defining: true,

        priority: 101,

        addAttributes() {
          return {
            textStyle: null,
            language: {
              default: null,
              renderHTML: attributes => {
                if (!attributes.language) {
                  return null;
                }

                return {
                  class: this.options.languageClassPrefix + attributes.language,
                };
              },
            },
          };
        },

        parseHTML() {
          return [
            {
              tag: 'pre',

              preserveWhitespace: 'full' as any,
            },
          ];
        },

        renderHTML({ HTMLAttributes }) {
          const allAttributes = mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
            'data-hook': ROOT,
            dir: 'auto',
          });
          return withBreakoutContainer(['pre', allAttributes, 0], { class: styles.codeParent });
        },

        addCommands() {
          return {
            setCodeBlock:
              attributes =>
              ({ commands }) => {
                return commands.updateTextNode(this.name, attributes);
              },
            toggleCodeBlock:
              attributes =>
              ({ commands }) => {
                return commands.toggleTextNode(this.name, Node_Type.PARAGRAPH, attributes);
              },
          };
        },

        addKeyboardShortcuts() {
          // escape node on triple enter
          const newLine = ({ editor }: $TSFixMe) => {
            const { state } = editor;
            const { selection } = state;
            const { $from, empty } = selection;

            if (!empty || $from.parent.type !== this.type) {
              return false;
            }

            const isAtEnd = $from.parentOffset === $from.parent.nodeSize - 2;
            const endsWithDoubleNewline = $from.parent.textContent.endsWith('\n\n');

            if (!isAtEnd || !endsWithDoubleNewline) {
              return false;
            }

            return editor
              .chain()
              .command(({ tr }: $TSFixMe) => {
                tr.delete($from.pos - 2, $from.pos);

                return true;
              })
              .exitCode()
              .run();
          };

          const tiptapKeyboardShortcuts = {
            Enter: newLine,
          };

          const newLineShortcuts: any = [];
          this.options.services.shortcuts.shortcuts.forEach((shortcut: $TSFixMe) => {
            if (shortcut.shortcut.name === 'NewLine') {
              newLineShortcuts.push(shortcut);
            }
          });

          newLineShortcuts.forEach((newLineShortcut: $TSFixMe) => {
            const modifier = newLineShortcut.keys.macOs.modifiers[0];
            const key = newLineShortcut.keys.macOs.key;
            const shortcutKey: keyof typeof tiptapKeyboardShortcuts = modifier
              ? `${modifier}-${key}`
              : key;
            tiptapKeyboardShortcuts[shortcutKey] = newLine;
          });

          return {
            // 'Mod-Alt-c': () => this.editor.commands.toggleCodeBlock(),

            // remove code block when at start of document or code block is empty
            Backspace: () => {
              const { empty, $anchor } = this.editor.state.selection;
              const isAtStart = $anchor.pos === 1;

              if (!empty || $anchor.parent.type.name !== this.name) {
                return false;
              }

              if (isAtStart || !$anchor.parent.textContent.length) {
                return this.editor.commands.normalizeNodes();
              }

              return false;
            },

            ...tiptapKeyboardShortcuts,
          };
        },

        addInputRules() {
          return [
            textblockTypeInputRule({
              find: backtickInputRegex,
              type: this.type,
              getAttributes: ({ groups }) => groups,
            }),
            textblockTypeInputRule({
              find: tildeInputRegex,
              type: this.type,
              getAttributes: ({ groups }) => groups,
            }),
          ];
        },

        addProseMirrorPlugins() {
          return [
            // this plugin creates a code block for pasted content from VS Code
            // we can also detect the copied code language
            new Plugin({
              key: new PluginKey('codeBlockVSCodeHandler'),
              props: {
                handlePaste: (view, event) => {
                  if (!event.clipboardData) {
                    return false;
                  }

                  // don’t create a new code block within code blocks
                  if (this.editor.isActive(this.type.name)) {
                    return false;
                  }

                  const text = event.clipboardData.getData('text/plain');
                  const vscode = event.clipboardData.getData('vscode-editor-data');
                  const vscodeData = vscode ? JSON.parse(vscode) : undefined;
                  const language = vscodeData?.mode;

                  if (!text || !language) {
                    return false;
                  }

                  const { tr } = view.state;

                  // create an empty code block
                  tr.replaceSelectionWith(this.type.create({ language }));

                  // put cursor inside the newly created code block
                  tr.setSelection(
                    TextSelection.near(tr.doc.resolve(Math.max(0, tr.selection.from - 2)))
                  );

                  // add text to code block
                  // strip carriage return chars from text pasted as code
                  // see: https://github.com/ProseMirror/prosemirror-view/commit/a50a6bcceb4ce52ac8fcc6162488d8875613aacd
                  tr.insertText(text.replace(/\r\n?/g, '\n'));

                  // store meta information
                  // this is useful for other plugins that depends on the paste event
                  // like the paste rule plugin
                  tr.setMeta('paste', true);

                  view.dispatch(tr);

                  return true;
                },
              },
            }),
          ];
        },
      };
    },
  }),
];
