import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Resolver } from './../../ricos-types/index.js';

export const isNodeOrCaptionSelected: Resolver<boolean> = (_, __, editor) => {
  const node = (editor?.state?.selection as Record<string, any> | undefined)?.node;
  const isCaption =
    editor?.state?.selection.$anchor.parent.type.name === Node_Type.CAPTION ||
    editor?.state?.selection.$head.parent.type.name === Node_Type.CAPTION;

  return !!node || isCaption;
};
